// Connect Four bitboard engine.
//
// Bit layout: column-major, HEIGHT+1 bits per column (top bit is a sentinel),
// so bit index for cell (col, row) is col * (HEIGHT + 1) + row.
// Total used bits: 7 * 7 = 49 -> we use BigInt.

export const WIDTH = 7;
export const HEIGHT = 6;
const H1 = HEIGHT + 1;

const BOTTOM: bigint[] = Array.from({ length: WIDTH }, (_, c) =>
  1n << BigInt(c * H1)
);
const COL_MASK: bigint[] = BOTTOM.map((b) => (b << BigInt(HEIGHT)) - b);
const TOP: bigint[] = BOTTOM.map((b) => b << BigInt(HEIGHT - 1));
export const FULL_BOARD: bigint = COL_MASK.reduce((a, b) => a | b);

/** True if `pos` contains four in a line. */
function alignment(pos: bigint): boolean {
  let m = pos & (pos >> 1n); // horizontal
  if (m & (m >> 2n)) return true;
  m = pos & (pos >> BigInt(H1)); // vertical
  if (m & (m >> BigInt(2 * H1))) return true;
  m = pos & (pos >> BigInt(H1 + 1)); // diagonal /
  if (m & (m >> BigInt(2 * (H1 + 1)))) return true;
  m = pos & (pos >> BigInt(H1 - 1)); // diagonal \
  if (m & (m >> BigInt(2 * (H1 - 1)))) return true;
  return false;
}

export class Board {
  /** stones of the player to move */
  cur: bigint = 0n;
  /** all stones */
  mask: bigint = 0n;
  /** plies played so far */
  moves = 0;

  static empty(): Board {
    return new Board();
  }

  /** Build a position by dropping pieces into columns; throws on illegal move. */
  static fromMoves(cols: number[]): Board {
    const b = new Board();
    for (const c of cols) {
      if (!b.canPlay(c)) throw new Error(`illegal move: column ${c}`);
      b.play(c);
    }
    return b;
  }

  canPlay(col: number): boolean {
    return (this.mask & TOP[col]) === 0n;
  }

  /** Drop a piece for the player to move. Returns true if that move won. */
  play(col: number): boolean {
    const m = (this.mask + BOTTOM[col]) & COL_MASK[col];
    const mover = this.cur;
    this.mask |= m;
    this.cur ^= m; // toggle to opponent
    this.moves++;
    return alignment(mover | m);
  }

  clone(): Board {
    const b = new Board();
    b.cur = this.cur;
    b.mask = this.mask;
    b.moves = this.moves;
    return b;
  }

  isFull(): boolean {
    return this.mask === FULL_BOARD;
  }

  /** Unique key identifying the position (side to move included). */
  key(): string {
    return `${this.cur}:${this.mask}`;
  }
}

// ---------------------------------------------------------------------------
// Evaluation: count open 2s and open 3s across all 69 four-cell windows.
// ---------------------------------------------------------------------------

const WINDOWS: bigint[] = (() => {
  const wins: bigint[] = [];
  const cell = (c: number, r: number) => 1n << BigInt(c * H1 + r);
  const addWindow = (c: number, r: number, dc: number, dr: number) => {
    let w = 0n;
    for (let i = 0; i < 4; i++) w |= cell(c + i * dc, r + i * dr);
    wins.push(w);
  };
  for (let c = 0; c < WIDTH; c++) {
    for (let r = 0; r < HEIGHT; r++) {
      if (c + 3 < WIDTH) addWindow(c, r, 1, 0);
      if (r + 3 < HEIGHT) addWindow(c, r, 0, 1);
      if (c + 3 < WIDTH && r + 3 < HEIGHT) addWindow(c, r, 1, 1);
      if (c + 3 < WIDTH && r - 3 >= 0) addWindow(c, r, 1, -1);
    }
  }
  return wins;
})();

function popcount(x: bigint): number {
  let n = 0;
  while (x) {
    x &= x - 1n;
    n++;
  }
  return n;
}

const SCORE_OPEN_2 = 10;
const SCORE_OPEN_3 = 50;

/** Static eval from the point of view of the player to move. Positive = better. */
export function evaluate(b: Board): number {
  const mine = b.cur;
  const theirs = b.mask ^ b.cur;
  let score = 0;
  for (const w of WINDOWS) {
    const myStones = mine & w;
    const theirStones = theirs & w;
    if (theirStones === 0n) {
      const n = popcount(myStones);
      if (n === 2) score += SCORE_OPEN_2;
      else if (n === 3) score += SCORE_OPEN_3;
    } else if (myStones === 0n) {
      const n = popcount(theirStones);
      // Slightly weight opponent threats higher -> prefer blocking.
      if (n === 2) score -= SCORE_OPEN_2 + 2;
      else if (n === 3) score -= SCORE_OPEN_3 + 10;
    }
  }
  return score;
}

