import { Board, evaluate } from "./engine.js";

export const WIN_SCORE = 1_000_000;

/** Center-first column ordering. */
export const MOVE_ORDER = [3, 2, 4, 1, 5, 0, 6];

interface NodeCounter {
  n: number;
}

/**
 * Negamax with alpha-beta pruning. Returns the score from the perspective of
 * the player to move. With alpha/beta at +/-Infinity everywhere it degrades
 * to pure minimax.
 */
function negamax(
  b: Board,
  depth: number,
  alpha: number,
  beta: number,
  counter: NodeCounter
): number {
  counter.n++;
  if (b.isFull()) return 0; // draw
  if (depth === 0) return evaluate(b);

  let best = -Infinity;
  for (const col of MOVE_ORDER) {
    if (!b.canPlay(col)) continue;
    const child = b.clone();
    const won = child.play(col);
    const score = won
      ? WIN_SCORE - child.moves // faster wins are better (and losses slower)
      : -negamax(child, depth - 1, -beta, -alpha, counter);
    if (score > best) best = score;
    if (best > alpha) alpha = best;
    if (alpha >= beta) break; // prune
  }
  return best;
}

export interface SearchResult {
  /** Best column, or -1 if no legal move. */
  col: number;
  score: number;
  nodes: number;
}

/**
 * Root search. When `prune` is false, runs pure minimax (no cutoffs) so node
 * counts can be compared against alpha-beta.
 */
export function analyze(b: Board, depth: number, prune = true): SearchResult {
  const counter: NodeCounter = { n: 0 };
  let bestCol = -1;
  let bestScore = -Infinity;
  let alpha = -Infinity;
  const beta = Infinity;

  for (const col of MOVE_ORDER) {
    if (!b.canPlay(col)) continue;
    counter.n++;
    const child = b.clone();
    const won = child.play(col);
    const score = won
      ? WIN_SCORE - child.moves
      : -negamax(
          child,
          depth - 1,
          prune ? -beta : -Infinity,
          prune ? -alpha : Infinity,
          counter
        );
    if (score > bestScore) {
      bestScore = score;
      bestCol = col;
    }
    if (prune && bestScore > alpha) alpha = bestScore;
  }
  return { col: bestCol, score: bestScore, nodes: counter.n };
}

