import { Board } from "./engine.js";
import { MOVE_ORDER } from "./search.js";

/**
 * Breadth-first enumeration of distinct positions reachable in exactly
 * `n` plies from the empty board, deduplicated by position key.
 * Returns an array where result[i] is the count after i+1 plies.
 */
export function countPositionsPerPly(n: number): number[] {
  // frontier maps position key -> board
  let frontier = new Map<string, Board>([["::start", Board.empty()]]);
  const counts: number[] = [];

  for (let ply = 1; ply <= n; ply++) {
    const next = new Map<string, Board>();
    for (const b of frontier.values()) {
      for (const col of MOVE_ORDER) {
        if (!b.canPlay(col)) continue;
        const child = b.clone();
        child.play(col);
        // No win is possible within 4 plies, so no early cutoff needed here,
        // but guard anyway to stay correct if n grows.
        next.set(child.key(), child);
      }
    }
    frontier = next;
    counts.push(next.size);
  }
  return counts;
}

