import { describe, expect, it } from "vitest";
import { Board } from "../src/engine.js";
import { analyze } from "../src/search.js";

describe("engine tactics", () => {
  it("finds an immediate vertical win", () => {
    // X: col 0 rows 0-2, O: col 1 rows 0-2 -> X to move wins with col 0.
    const b = Board.fromMoves([0, 1, 0, 1, 0, 1]);
    const result = analyze(b, 8);
    console.log(`win test -> col ${result.col}, score ${result.score}, nodes ${result.nodes}`);
    expect(result.col).toBe(0);
    expect(result.score).toBeGreaterThanOrEqual(999_000);
  });

  it("blocks an opponent's immediate win", () => {
    // O has three in column 1 (rows 0-2); X to move must play col 1.
    const b = Board.fromMoves([0, 1, 0, 1, 0]);
    const result = analyze(b, 8);
    console.log(`block test -> col ${result.col}, score ${result.score}, nodes ${result.nodes}`);
    expect(result.col).toBe(1);
  });
});

